package org.mockito.internal.stubbing.answers;

import org.mockito.exceptions.Reporter;
import org.mockito.internal.invocation.Invocation;
import org.mockito.stubbing.Answer;

public class AnswersValidator {

    private Reporter reportEngine = new Reporter();

    public void validate(Answer<?> answerToCheck, Invocation methodInvocation) {
        if (ThrowsException.class.isInstance(answerToCheck)) {
            validateException((ThrowsException) answerToCheck, methodInvocation);
        }

        if (Returns.class.isInstance(answerToCheck)) {
            validateReturnValue((Returns) answerToCheck, methodInvocation);
        }

        if (DoesNothing.class.isInstance(answerToCheck)) {
            validateDoNothing((DoesNothing) answerToCheck, methodInvocation);
        }

    }


    private void validateDoNothing(DoesNothing theAnswer, Invocation methodInvocation) {
        boolean methodIsVoid = methodInvocation.isVoid();
        if (!methodIsVoid) {
            reportEngine.onlyVoidMethodsCanBeSetToDoNothing();
        }
    }

    private void validateReturnValue(Returns theAnswer, Invocation methodInvocation) {
        boolean voidMethod = methodInvocation.isVoid();
        if (voidMethod) {
            reportEngine.cannotStubVoidMethodWithAReturnValue();
        }

        boolean nullReturned = theAnswer.returnsNull();
        boolean primitiveExpected = methodInvocation.returnsPrimitive();

        if (nullReturned && primitiveExpected) {
            reportEngine.wrongTypeOfReturnValue(methodInvocation.printMethodReturnType(), "null", methodInvocation.getMethodName());
        }

        if (!nullReturned && !methodInvocation.isValidReturnType(theAnswer.getReturnType())) {
            reportEngine.wrongTypeOfReturnValue(methodInvocation.printMethodReturnType(), theAnswer.printReturnType(), methodInvocation.getMethodName());
        }
    }

    private void validateException(ThrowsException theAnswer, Invocation methodInvocation) {
        Throwable throwableToThrow = theAnswer.getThrowable();
        if (null == throwableToThrow) {
            reportEngine.cannotStubWithNullThrowable();
        }

        if ((throwableToThrow instanceof RuntimeException) || (throwableToThrow instanceof Error)) {
            return;
        }

        if (!methodInvocation.isValidException(throwableToThrow)) {
            reportEngine.checkedExceptionInvalid(throwableToThrow);
        }
    }
}
